INSERT INTO `v1_f4dee4921398b6ce3a6b064828e85d1a32629cd34200ef45e74826ef8339d0ee` VALUES ("2030/01/01 14:59:59", 1, 3.414, -416.5, 1, "2025/01/31 12:00:00", 62, 1000001, 1, "カリン", 190805, "ミッションをクリアすると、\n報酬がもらえますよ！\n頑張ってください", 0.0, 2);
INSERT INTO `v1_f4dee4921398b6ce3a6b064828e85d1a32629cd34200ef45e74826ef8339d0ee` VALUES ("2030/01/01 14:59:59", 1, 3.099, -416.5, 2, "2025/01/31 12:00:00", 62, 1000002, 1, "カリン", 190805, "ミッションをクリアして、\n報酬をゲットしましょう！", 0.0, 2);
INSERT INTO `v1_f4dee4921398b6ce3a6b064828e85d1a32629cd34200ef45e74826ef8339d0ee` VALUES ("2030/01/01 14:59:59", 1, 2.801, -416.5, 3, "2025/01/31 12:00:00", 63, 1000003, 1, "カリン", 190805, "受け取ることができる\n報酬があるようです\n確認してみてください", 0.0, 2);
INSERT INTO `v1_f4dee4921398b6ce3a6b064828e85d1a32629cd34200ef45e74826ef8339d0ee` VALUES ("2030/01/01 14:59:59", 1, 0.0, -416.5, 4, "2025/01/31 12:00:00", 63, 1000004, 2, "カリン", 190805, "報酬がもらえますよ！\nチェックしてみてください", 0.0, 2);
INSERT INTO `v1_f4dee4921398b6ce3a6b064828e85d1a32629cd34200ef45e74826ef8339d0ee` VALUES ("2030/01/01 14:59:59", 1, 2.12, -363.0, 5, "2025/01/31 12:00:00", 64, 1000005, 2, "カリン", 190805, "ギルド管理協会です！\nイベント報酬券をお持ちでしたら、様々なアイテムと交換できますよ", 0.0, 1);
INSERT INTO `v1_f4dee4921398b6ce3a6b064828e85d1a32629cd34200ef45e74826ef8339d0ee` VALUES ("2030/01/01 14:59:59", 1, 1.68, -363.0, 6, "2025/01/31 12:00:00", 64, 1000006, 1, "カリン", 190805, "お疲れさまです！\nこちらでイベント報酬券とアイテムを交換することができますよ", 0.0, 2);
INSERT INTO `v1_f4dee4921398b6ce3a6b064828e85d1a32629cd34200ef45e74826ef8339d0ee` VALUES ("2030/01/01 14:59:59", 1, 2.33, -363.0, 7, "2025/01/31 12:00:00", 64, 1000007, 2, "カリン", 190805, "いつもありがとうございます！\n報酬交換ですか？\nでは、イベント報酬券とお引き換えいたしますね", 0.0, 1);
INSERT INTO `v1_f4dee4921398b6ce3a6b064828e85d1a32629cd34200ef45e74826ef8339d0ee` VALUES ("2030/01/01 14:59:59", 10201, 5.18, -285.0, 101, "2025/01/31 12:00:00", 61, 1020101, 3, "ラビリスタ", 133701, "今度の敵は、アタシにとっても\n放ってはおけない存在だ\n少年、アタシも全力で行くからさ\n一緒に守ろう、この世界を", -6.0, 7);
INSERT INTO `v1_f4dee4921398b6ce3a6b064828e85d1a32629cd34200ef45e74826ef8339d0ee` VALUES ("2030/01/01 14:59:59", 10201, 8.77, -285.0, 201, "2025/01/31 12:00:00", 61, 1020102, 1, "クリスティーナ", 133901, "退屈の吹き飛ぶような\n戦いの気配がするなぁ坊や\nさっさとワタシをそこへ連れてゆけ\n世界も守ってやるさ、ついでにな", -2.0, 2);
INSERT INTO `v1_f4dee4921398b6ce3a6b064828e85d1a32629cd34200ef45e74826ef8339d0ee` VALUES ("2030/01/01 14:59:59", 10201, 15.5, -285.0, 301, "2025/01/31 12:00:00", 61, 1020103, 6, "ネネカ", 133801, "おや、私の力が必要……と？\nグレゴールが手伝うそうですよ\n私は戦わないのか、という顔ですね\n……考えておきます", 0.0, 1);
INSERT INTO `v1_f4dee4921398b6ce3a6b064828e85d1a32629cd34200ef45e74826ef8339d0ee` VALUES ("2030/01/01 14:59:59", 10202, 9.061, -285.0, 101, "2025/02/28 12:00:00", 61, 1020201, 2, "ランファ", 134301, "わたしだけの歌…\n一緒に、探してくれる…？\nあなたがいれば…\nもっとがんばれるから…", 0.0, 5);
INSERT INTO `v1_f4dee4921398b6ce3a6b064828e85d1a32629cd34200ef45e74826ef8339d0ee` VALUES ("2030/01/01 14:59:59", 10202, 7.699, -285.0, 201, "2025/02/28 12:00:00", 61, 1020202, 1, "チカ", 134401, "同じ唱喚士として、仲間として\n私にできることをします\n…これも、あなたが\n背中を押してくれたおかげですよ", 0.0, 2);
INSERT INTO `v1_f4dee4921398b6ce3a6b064828e85d1a32629cd34200ef45e74826ef8339d0ee` VALUES ("2030/01/01 14:59:59", 10203, 8.595, -285.0, 101, "2025/03/31 12:00:00", 61, 1020301, 1, "アオイ", 134601, "世界の平和が私とクローチェさんに\nかかってるんですよね？\nぼっちには過大すぎる期待ですけど\nふ、二人でなら背負ってみせます！", 0.0, 2);
INSERT INTO `v1_f4dee4921398b6ce3a6b064828e85d1a32629cd34200ef45e74826ef8339d0ee` VALUES ("2030/01/01 14:59:59", 10203, 7.758, -285.0, 201, "2025/03/31 12:00:00", 61, 1020302, 1, "クローチェ", 134501, "新しく手に入れたこの翼で…\nナイトさんがどこにいたって\nわたし、駆けつけちゃいますよっ！\nクローチェ・エアリアル発進ですっ", 0.0, 2);
INSERT INTO `v1_f4dee4921398b6ce3a6b064828e85d1a32629cd34200ef45e74826ef8339d0ee` VALUES ("2030/01/01 14:59:59", 10204, 7.0, -285.0, 101, "2025/04/30 12:00:00", 61, 1020401, 2, "ルイズマリー", 132302, "今日はダーリンとの初デート♪\n二人でショッピングして、その後は\n…って私、指名手配されてる！？\nちょ、た…助けてダーリン～！！", 0.0, 6);
INSERT INTO `v1_f4dee4921398b6ce3a6b064828e85d1a32629cd34200ef45e74826ef8339d0ee` VALUES ("2030/01/01 14:59:59", 10204, 7.904, -285.0, 201, "2025/04/30 12:00:00", 61, 1020402, 1, "イロハ", 132402, "ルイちゃんのおばあちゃん優しくて\nいつもにこにこで、イロハ大好き♪\nでも一番好きなのは、角がすっごく\n大きくてかっこいいとこなんだ～♪", 0.0, 2);
INSERT INTO `v1_f4dee4921398b6ce3a6b064828e85d1a32629cd34200ef45e74826ef8339d0ee` VALUES ("2030/01/01 14:59:59", 10204, 8.487, -285.0, 301, "2025/04/30 12:00:00", 61, 1020403, 4, "ソノ", 132502, "ノゾミちゃんのおかげで売上が安定\nしてきたのに、臨時休業、痛すぎる\n…ま、ルイちゃんのために\n一肌脱ぐか。行くよイロハ～", 0.0, 2);
INSERT INTO `v1_f4dee4921398b6ce3a6b064828e85d1a32629cd34200ef45e74826ef8339d0ee` VALUES ("2030/01/01 14:59:59", 10205, 8.763, -285.0, 101, "2025/05/31 12:00:00", 61, 1020502, 1, "カノン", 134901, "ヲ～ッホッホ♪\nあたくし様と同じお空気を吸える\nお幸運を噛みしめなさいですわ～♪\nヲ～ッホッホッホ～♪", 0.0, 2);
INSERT INTO `v1_f4dee4921398b6ce3a6b064828e85d1a32629cd34200ef45e74826ef8339d0ee` VALUES ("2030/01/01 14:59:59", 10205, 6.417, -285.0, 201, "2025/05/31 12:00:00", 61, 1020503, 1, "ツムギ", 134801, "いきますよ騎士さん！\nカノンさんと力を合わせて…力を…\n…本当にあの人なんなんです？\nこれまでになく不安なんですけど！", 0.0, 3);
INSERT INTO `v1_f4dee4921398b6ce3a6b064828e85d1a32629cd34200ef45e74826ef8339d0ee` VALUES ("2030/01/01 14:59:59", 10206, 10.335, -285.0, 101, "2025/06/30 12:00:00", 61, 1020601, 3, "エリス", 135001, "『願いが叶う海岸』か…怪しい\nだというのに、阿賀斗紫布菜たちは\n呑気に戯れている…見ていられない\n騎士クンは、わたしが守ってみせる", 0.0, 7);
INSERT INTO `v1_f4dee4921398b6ce3a6b064828e85d1a32629cd34200ef45e74826ef8339d0ee` VALUES ("2030/01/01 14:59:59", 10206, 6.281, -285.0, 201, "2025/06/30 12:00:00", 61, 1020602, 2, "シェフィ", 135101, "せっかくの夏休みなんだし\nたまにはビーチでゆっくりしましょ\n…え、もしかしてこの夏もあんまり\n休めなかったりする感じなの？", 0.0, 4);
INSERT INTO `v1_f4dee4921398b6ce3a6b064828e85d1a32629cd34200ef45e74826ef8339d0ee` VALUES ("2030/01/01 14:59:59", 10206, 12.244, -285.0, 301, "2025/06/30 12:00:00", 61, 1020603, 1, "プレシア", 135201, "いっぱい。たべて\nおおきく。なると\nせーぎ。まもれる。はず\nお兄。いっしょに。スイカ。たべよ", 0.0, 2);
INSERT INTO `v1_f4dee4921398b6ce3a6b064828e85d1a32629cd34200ef45e74826ef8339d0ee` VALUES ("2030/01/01 14:59:59", 10207, 6.339, -285.0, 101, "2025/07/31 12:00:00", 61, 1020701, 2, "クリア", 135301, "ひと夏の冒険のはじまりです！\nアネモネさんも楽しんでくれたら\n…できれば、もう少し\n仲良くなれたらうれしいな…", 0.0, 8);
INSERT INTO `v1_f4dee4921398b6ce3a6b064828e85d1a32629cd34200ef45e74826ef8339d0ee` VALUES ("2030/01/01 14:59:59", 10207, 8.184, -285.0, 201, "2025/07/31 12:00:00", 61, 1020702, 7, "アネモネ", 135401, "─幻の花…\n本当にあるのか謎─ですけど\n探すくらいは、\n付き合ってもいいです", 0.0, 9);
INSERT INTO `v1_f4dee4921398b6ce3a6b064828e85d1a32629cd34200ef45e74826ef8339d0ee` VALUES ("2030/01/01 14:59:59", 10208, 3.906, -285.0, 101, "2025/08/31 12:00:00", 61, 1020801, 9, "アイラ", 129101, "あははっ！　笑う門には福来る！\n笑ってればきっと、複製世界にも\n未来はやってくるって信じてる！\nそうだよね、シナツちゃん！", 0.0, 2);
INSERT INTO `v1_f4dee4921398b6ce3a6b064828e85d1a32629cd34200ef45e74826ef8339d0ee` VALUES ("2030/01/01 14:59:59", 10208, 14.465, -285.0, 201, "2025/08/31 12:00:00", 61, 1020802, 1, "シナツ", 129201, "繰り返されるリセットの先の未来\n何度願っても手に入らなかった未来\n…でも、私は諦めない。絶対にだ\nキミも同じだろ…アイラ？", 0.0, 2);
INSERT INTO `v1_f4dee4921398b6ce3a6b064828e85d1a32629cd34200ef45e74826ef8339d0ee` VALUES ("2030/01/01 14:59:59", 10208, 8.662, -285.0, 301, "2025/08/31 12:00:00", 61, 1020803, 4, "ヒヨリ", 100101, "アイラの世界のみんなも、\n一生懸命生きてるんだ…！\n…なのに、世界の危機だなんて！\nあたし、絶対、絶対力になるよ！", 0.0, 3);
INSERT INTO `v1_f4dee4921398b6ce3a6b064828e85d1a32629cd34200ef45e74826ef8339d0ee` VALUES ("2030/01/01 14:59:59", 10208, 10.915, -285.0, 401, "2025/08/31 12:00:00", 61, 1020804, 1, "レイ", 100301, "シナツ…もう一人の私\n彼女が大切にしている世界を\n絶対に終わらせはしない…！\n彼女と笑い合える未来のために！", 0.0, 3);
INSERT INTO `v1_f4dee4921398b6ce3a6b064828e85d1a32629cd34200ef45e74826ef8339d0ee` VALUES ("2030/01/01 14:59:59", 10209, 6.042, -285.0, 101, "2025/09/30 12:00:00", 61, 1020901, 1, "ユキノ", 135802, "あ、ど、ども…\nあ、あんま見ねぇでくれっと\nその、恥ずかしくて…\n体が熱くなって、溶けちまう…", 0.0, 7);
INSERT INTO `v1_f4dee4921398b6ce3a6b064828e85d1a32629cd34200ef45e74826ef8339d0ee` VALUES ("2030/01/01 14:59:59", 10209, 9.402, -285.0, 201, "2025/09/30 12:00:00", 61, 1020902, 4, "サツキ", 135903, "なんで俺が幽霊に…意味不明だ\nこれじゃ死んでも死にきれねェ\n悪ィがこれも何かの縁だ、\nよろしく頼むぜ騎士公", 0.0, 1);
INSERT INTO `v1_f4dee4921398b6ce3a6b064828e85d1a32629cd34200ef45e74826ef8339d0ee` VALUES ("2030/01/01 14:59:59", 10209, 8.16, -285.0, 301, "2025/09/30 12:00:00", 61, 1020903, 8, "ルルィ", 136902, "う、うじゅる…\nサツキ姉しゃまを助けるためにも\nまずは、腹ごしらえでしゅね…！\nタコ焼き、召し上がってくだしゃい", 0.0, 1);
INSERT INTO `v1_f4dee4921398b6ce3a6b064828e85d1a32629cd34200ef45e74826ef8339d0ee` VALUES ("2030/01/01 14:59:59", 10210, 5.0, -285.0, 101, "2025/10/31 12:00:00", 61, 1021001, 3, "カスミ", 137401, "ひさしぶりのジオ・ゲヘナ\n歓迎パーティーで起きた殺人事件！\nランドソルの名探偵の名にかけて\n解き明かしてみせようじゃないか！", 0.0, 2);
INSERT INTO `v1_f4dee4921398b6ce3a6b064828e85d1a32629cd34200ef45e74826ef8339d0ee` VALUES ("2030/01/01 14:59:59", 10210, 8.12, -285.0, 201, "2025/10/31 12:00:00", 61, 1021002, 4, "アラクネ", 136001, "…わたしはどこの誰なのでしょう\nどこから来てどこへ行くのでしょう\nこの事件の真相が分かれば、\n何かが掴めるような気がいたします", 0.0, 1);
INSERT INTO `v1_f4dee4921398b6ce3a6b064828e85d1a32629cd34200ef45e74826ef8339d0ee` VALUES ("2030/01/01 14:59:59", 10210, 6.386, -285.0, 301, "2025/10/31 12:00:00", 61, 1021003, 4, "ナーナ", 136202, "ナーナ、すいりとかろんぱとか、\nむずかしくてわかんないけど…\nお友だちとドーナツのためならっ\nせーいっぱいがんばるよっ！", 0.0, 2);
INSERT INTO `v1_f4dee4921398b6ce3a6b064828e85d1a32629cd34200ef45e74826ef8339d0ee` VALUES ("2030/01/01 14:59:59", 10211, 7.438, -285.0, 101, "2025/11/30 12:00:00", 61, 1021101, 3, "ユイ", 136402, "騎士クンに想いを伝えたい…だから\nミソラちゃん、わたしがんばるね！\n…あれ？　わたし、なんでこんなに\n必死になってるんだろう…？", 0.0, 4);
INSERT INTO `v1_f4dee4921398b6ce3a6b064828e85d1a32629cd34200ef45e74826ef8339d0ee` VALUES ("2030/01/01 14:59:59", 10211, 8.35, -285.0, 201, "2025/11/30 12:00:00", 61, 1021102, 1, "ミソラ", 136302, "騎士さんとのデートはわたしに\nお任せです★　なのでユイさんは\n安心して計画に専念して…たくさん\nドキドキしちゃってくださいね", 0.0, 5);
INSERT INTO `v1_f4dee4921398b6ce3a6b064828e85d1a32629cd34200ef45e74826ef8339d0ee` VALUES ("2030/01/01 14:59:59", 10212, 5.0, -285.0, 101, "2025/12/31 12:00:00", 61, 1021201, 1, "シズル", 136501, "新しい年がやってくるね！\nお正月の料理も飾りつけも、\nお姉ちゃんにお任せだよ♪\nみんなで楽しく新年を迎えよう！", 0.0, 2);
INSERT INTO `v1_f4dee4921398b6ce3a6b064828e85d1a32629cd34200ef45e74826ef8339d0ee` VALUES ("2030/01/01 14:59:59", 10212, 5.25, -285.0, 201, "2025/12/31 12:00:00", 61, 1021202, 1, "リノ", 137902, "おうちの掃除もトラブルも、 \n世界を揺るがす大ピンチも！\n今年のことは今年のうちに \nサッサと片付けちゃいますっ！", 0.0, 2);
INSERT INTO `v1_f4dee4921398b6ce3a6b064828e85d1a32629cd34200ef45e74826ef8339d0ee` VALUES ("2030/01/01 14:59:59", 10212, 7.5, -285.0, 301, "2025/12/31 12:00:00", 61, 1021203, 1, "ラビリスタ", 106801, "年の瀬はギルドマスターも\nつい駆け回っちゃう忙しい時期だ！\n一年いろいろあったけど\nお互いイイ年を迎えよう、少年！", 0.0, 2);
INSERT INTO `v1_f4dee4921398b6ce3a6b064828e85d1a32629cd34200ef45e74826ef8339d0ee` VALUES ("2030/01/01 14:59:59", 10213, 8.204, -285.0, 101, "2026/01/31 12:00:00", 61, 1021301, 1, "ライラエル", 126501, "漂う異国の料理の香り…それだけで\n世界中を旅した気分に浸れますね\nふふ、ほらクローチェ\nあまりはしゃぎすぎないように…♪", 0.0, 2);
INSERT INTO `v1_f4dee4921398b6ce3a6b064828e85d1a32629cd34200ef45e74826ef8339d0ee` VALUES ("2030/01/01 14:59:59", 10213, 7.176, -285.0, 201, "2026/01/31 12:00:00", 61, 1021302, 1, "ネフィ＝ネラ", 129701, "異界の姫君と煮炊きにて競い合う…\n感奮興起、いとをかし\n華やかなる祭典と相成るよう、一肌\n脱がせていただきとう存じまする", 0.0, 2);
INSERT INTO `v1_f4dee4921398b6ce3a6b064828e85d1a32629cd34200ef45e74826ef8339d0ee` VALUES ("2030/01/01 14:59:59", 10213, 8.602, -285.0, 301, "2026/01/31 12:00:00", 61, 1021303, 1, "ヴァイオレット", 133101, "『ビストロプリンセス』のために\n料理の特訓を重ねてまいりました\nこの料理で騎士様の…い、いえ\n皆様の心とお腹を満たしますわ！", 0.0, 5);
INSERT INTO `v1_f4dee4921398b6ce3a6b064828e85d1a32629cd34200ef45e74826ef8339d0ee` VALUES ("2030/01/01 14:59:59", 10213, 10.14, -285.0, 102, "2026/02/06 12:00:00", 61, 1021304, 1, "ライラエル", 138101, "多様な味わいが織りなすハーモニー\nそれこそが我が国の矜持です\nもしもそれを乱すようであれば\nわたしも優しくはありませんよ？", 0.0, 3);
INSERT INTO `v1_f4dee4921398b6ce3a6b064828e85d1a32629cd34200ef45e74826ef8339d0ee` VALUES ("2030/01/01 14:59:59", 10213, 10.152, -285.0, 202, "2026/02/06 12:00:00", 61, 1021305, 1, "ネフィ＝ネラ", 138201, "煉獄の穢土にてひと際輝く民草の心\n此れを守護りまするがわっちの責務\n如何な困難待ち受けようと\n不退転の矜持に揺らぎはありんせん", 0.0, 7);
INSERT INTO `v1_f4dee4921398b6ce3a6b064828e85d1a32629cd34200ef45e74826ef8339d0ee` VALUES ("2030/01/01 14:59:59", 10213, 9.688, -285.0, 302, "2026/02/06 12:00:00", 61, 1021306, 4, "ヴァイオレット", 138001, "裏世界の皆様は危機を脱し、\n残るはランドソルの皆様のみ…\n彼らを救い出すために、どうか…\nお立ち下さいペコリーヌ姫…！", 0.0, 3);
INSERT INTO `v1_f4dee4921398b6ce3a6b064828e85d1a32629cd34200ef45e74826ef8339d0ee` VALUES ("2030/01/01 14:59:59", 10213, 5.928, -285.0, 401, "2026/02/12 12:00:00", 61, 1021307, 2, "ペコリーヌ", 138301, "みなさん、お待たせしちゃいました\nペコリーヌ、完全復活です☆\nみなさんの食卓を守るため\nもう二度と、わたしはめげません！", 0.0, 1);
INSERT INTO `v1_f4dee4921398b6ce3a6b064828e85d1a32629cd34200ef45e74826ef8339d0ee` VALUES ("2030/01/01 14:59:59", 10214, 9.19, -285.0, 101, "2026/02/28 12:00:00", 61, 1021401, 4, "ワカナ", 138702, "成行きで参加することになっちゃっ\nた尻相撲大会。ううっ、恥ずかしい\nけどやるしかないよね。…騎士さん\nいっぱい応援してくださいね？", 0.0, 2);
INSERT INTO `v1_f4dee4921398b6ce3a6b064828e85d1a32629cd34200ef45e74826ef8339d0ee` VALUES ("2030/01/01 14:59:59", 10214, 8.724, -285.0, 201, "2026/02/28 12:00:00", 61, 1021402, 1, "シオリ", 138802, "「お姉ちゃんを守れる自分になる」\nあの日の約束、今こそ果たしてみせ\nます。例えお姉ちゃんに背くことに\nなっても。例えそれが尻相撲でも！", 0.0, 3);
INSERT INTO `v1_f4dee4921398b6ce3a6b064828e85d1a32629cd34200ef45e74826ef8339d0ee` VALUES ("2030/01/01 14:59:59", 10215, 7.758, -285.0, 101, "2026/03/31 12:00:00", 61, 1021501, 4, "グレイス", 138902, "私がへんたいふしんしゃさんって…\nただ生きているだけなのに、ひどい\n…まぁ死んでるんですけど…とか\n言ってる暇もない感じですか？", 0.0, 1);
INSERT INTO `v1_f4dee4921398b6ce3a6b064828e85d1a32629cd34200ef45e74826ef8339d0ee` VALUES ("2030/01/01 14:59:59", 10215, 6.375, -285.0, 201, "2026/03/31 12:00:00", 61, 1021502, 6, "キョウカ", 139002, "あの、助けてください！\n私がへんたいふしんしゃさんに\nなっちゃったみたいなんです…！\nどういう意味かは私もわかりません", 0.0, 4);
INSERT INTO `v1_f4dee4921398b6ce3a6b064828e85d1a32629cd34200ef45e74826ef8339d0ee` VALUES ("2030/01/01 14:59:59", 10215, 6.173, -285.0, 301, "2026/03/31 12:00:00", 61, 1021503, 6, "ルルィ", 136902, "ましゃか、グレイス姉しゃまたちが\nへんたいふしんしゃさんだなんて…\n騎士しゃん。あたちたちも協力ちて\n二人の破滅エンドを回避ちましょう", 0.0, 1);
INSERT INTO `v1_f4dee4921398b6ce3a6b064828e85d1a32629cd34200ef45e74826ef8339d0ee` VALUES ("2030/01/01 14:59:59", 10216, 4.202, -285.0, 101, "2026/04/30 12:00:00", 61, 1021601, 6, "ミホ", 139202, "違う世界に来ちゃうし、\n驚きの連続だけど…\nわたしも精いっぱい頑張ります！\nアストルムのみんなと一緒に！", 0.0, 2);
INSERT INTO `v1_f4dee4921398b6ce3a6b064828e85d1a32629cd34200ef45e74826ef8339d0ee` VALUES ("2030/01/01 14:59:59", 10216, 2.842, -285.0, 201, "2026/04/30 12:00:00", 61, 1021602, 6, "マホ", 139302, "想定外の事象が発生したな…だが\nいかなる苦境も切り抜けてみせる\nいつもの自分とは違う姿になっても\nわたしはわたし、西住流だ", 0.0, 1);
INSERT INTO `v1_f4dee4921398b6ce3a6b064828e85d1a32629cd34200ef45e74826ef8339d0ee` VALUES ("2030/01/01 14:59:59", 10216, 4.598, -285.0, 301, "2026/04/30 12:00:00", 61, 1021603, 4, "エリカ", 139402, "何でこんなことになっているのか\n全然わからないけど、迷ってる暇は\nないわ。黒森峰の次期隊長として、\n前進あるのみ！　これも戦車道よ！", 0.0, 1);
INSERT INTO `v1_f4dee4921398b6ce3a6b064828e85d1a32629cd34200ef45e74826ef8339d0ee` VALUES ("2030/01/01 14:59:59", 10217, 6.533, -285.0, 101, "2026/05/31 12:00:00", 61, 1021701, 4, "リリ", 125802, "わたくしたちの悲願は、ロストさせ\nてしまった方々をお助けすること…\nそのためなら、どのような辛苦にも\n耐え抜いてみせます…！", 0.0, 3);
INSERT INTO `v1_f4dee4921398b6ce3a6b064828e85d1a32629cd34200ef45e74826ef8339d0ee` VALUES ("2030/01/01 14:59:59", 10217, 5.0, -285.0, 301, "2026/05/31 12:00:00", 61, 1021702, 3, "プレシア", 126102, "みんなも。せーぎも。\nクリアも。パパ、も。\nぜったい、たすける。\nみててね。お兄。", 0.0, 3);
INSERT INTO `v1_f4dee4921398b6ce3a6b064828e85d1a32629cd34200ef45e74826ef8339d0ee` VALUES ("2030/01/01 14:59:59", 10217, 5.214, -285.0, 201, "2026/05/31 12:00:00", 61, 1021703, 3, "クリア", 126002, "癒しの力を使うこと…\nもう、ためらいません！\nモネちゃんやお兄さん…\nみんなに許してもらうためにも！", 0.0, 4);
INSERT INTO `v1_f4dee4921398b6ce3a6b064828e85d1a32629cd34200ef45e74826ef8339d0ee` VALUES ("2030/01/01 14:59:59", 10217, 8.781, -285.0, 102, "2026/05/31 12:00:00", 61, 1021704, 1, "リリ", 139501, "ヴァルキュリア─皆様を助けたい\nという願いを、力にできるのなら…\nわたくしたちは、きっと誰にも\n負けません！　一意専心です…！", 0.0, 3);
INSERT INTO `v1_f4dee4921398b6ce3a6b064828e85d1a32629cd34200ef45e74826ef8339d0ee` VALUES ("2030/01/01 14:59:59", 10217, 6.529, -285.0, 202, "2026/05/31 12:00:00", 61, 1021705, 2, "クリア", 139601, "このヴァルキュリアって職業、\nまるで天使みたいな格好ですよね\nうーん…『聖女』ちゃんって\n呼ばれるよりは、マシかな？", 0.0, 1);
INSERT INTO `v1_f4dee4921398b6ce3a6b064828e85d1a32629cd34200ef45e74826ef8339d0ee` VALUES ("2030/01/01 14:59:59", 10217, 3.195, -285.0, 302, "2026/05/31 12:00:00", 61, 1021706, 3, "プレシア", 139701, "ばるきり。もーど。\nはね。まっしろ。\nはっぴーちゃんと。おなじ。\nいいかんじ。", 0.0, 2);
INSERT INTO `v1_f4dee4921398b6ce3a6b064828e85d1a32629cd34200ef45e74826ef8339d0ee` VALUES ("2030/01/01 14:59:59", 10218, 12.43, -285.0, 101, "2026/06/30 12:00:00", 61, 1021801, 2, "ルイズマリー", 139902, "ダーリンと一緒に南の島で\nリゾート開発なんて夢みたい♪\nああ…幸せ、最高の夏だわ…\n触れたら爆発さえしなければ～…っ", 0.0, 3);
INSERT INTO `v1_f4dee4921398b6ce3a6b064828e85d1a32629cd34200ef45e74826ef8339d0ee` VALUES ("2030/01/01 14:59:59", 10218, 6.35, -285.0, 201, "2026/06/30 12:00:00", 61, 1021802, 2, "クレジッタ", 140001, "青い空、白い雲…無人島リゾートで\n大儲けですわ～♪　こらこらそこ、\nイチャついてるんじゃないですのよ\n触れたらドカンですわよ、ドカン！", 0.0, 3);
INSERT INTO `v1_f4dee4921398b6ce3a6b064828e85d1a32629cd34200ef45e74826ef8339d0ee` VALUES ("2030/01/01 14:59:59", 10219, 10.23, -285.0, 101, "2026/07/31 12:00:00", 61, 1021901, 1, "フブキ", 140102, "みんなはかわいいぼくを見られて、\nぼくはみんなからラヴをもらう♡\n最高のウィンウィンだよね、これ♡\nで、最後はお兄さんをドレーに…♡", 0.0, 5);
INSERT INTO `v1_f4dee4921398b6ce3a6b064828e85d1a32629cd34200ef45e74826ef8339d0ee` VALUES ("2030/01/01 14:59:59", 10219, 5.584, -285.0, 201, "2026/07/31 12:00:00", 61, 1021902, 1, "ヴァンピィ", 140201, "けんぞくとたくさん遊ぶためにも、\nみんなからラヴをもらわなくちゃ♪\nバズっちゃおー作戦、\n一緒に考えてね！　けんぞくぅ♪", 0.0, 2);
INSERT INTO `v1_f4dee4921398b6ce3a6b064828e85d1a32629cd34200ef45e74826ef8339d0ee` VALUES ("2030/01/01 14:59:59", 2, 3.414, -416.5, 1, "2026/04/10 12:00:00", 62, 2000001, 1, "カリン", 190801, "ミッションをクリアすると、\n報酬がもらえますよ！\n頑張ってください", 0.0, 2);
INSERT INTO `v1_f4dee4921398b6ce3a6b064828e85d1a32629cd34200ef45e74826ef8339d0ee` VALUES ("2030/01/01 14:59:59", 2, 3.099, -416.5, 2, "2026/04/10 12:00:00", 62, 2000002, 1, "カリン", 190801, "ミッションをクリアして、\n報酬をゲットしましょう！", 0.0, 2);
INSERT INTO `v1_f4dee4921398b6ce3a6b064828e85d1a32629cd34200ef45e74826ef8339d0ee` VALUES ("2030/01/01 14:59:59", 2, 2.801, -416.5, 3, "2026/04/10 12:00:00", 63, 2000003, 1, "カリン", 190801, "受け取ることができる\n報酬があるようです\n確認してみてください", 0.0, 2);
INSERT INTO `v1_f4dee4921398b6ce3a6b064828e85d1a32629cd34200ef45e74826ef8339d0ee` VALUES ("2030/01/01 14:59:59", 2, 0.0, -416.5, 4, "2026/04/10 12:00:00", 63, 2000004, 2, "カリン", 190801, "報酬がもらえますよ！\nチェックしてみてください", 0.0, 2);
INSERT INTO `v1_f4dee4921398b6ce3a6b064828e85d1a32629cd34200ef45e74826ef8339d0ee` VALUES ("2030/01/01 14:59:59", 2, 2.12, -363.0, 5, "2026/04/10 12:00:00", 64, 2000005, 2, "カリン", 190801, "ギルド管理協会です！\nイベント報酬券をお持ちでしたら、様々なアイテムと交換できますよ", 0.0, 1);
INSERT INTO `v1_f4dee4921398b6ce3a6b064828e85d1a32629cd34200ef45e74826ef8339d0ee` VALUES ("2030/01/01 14:59:59", 2, 1.68, -363.0, 6, "2026/04/10 12:00:00", 64, 2000006, 1, "カリン", 190801, "お疲れさまです！\nこちらでイベント報酬券とアイテムを交換することができますよ", 0.0, 2);
INSERT INTO `v1_f4dee4921398b6ce3a6b064828e85d1a32629cd34200ef45e74826ef8339d0ee` VALUES ("2030/01/01 14:59:59", 2, 2.33, -363.0, 7, "2026/04/10 12:00:00", 64, 2000007, 2, "カリン", 190801, "いつもありがとうございます！\n報酬交換ですか？\nでは、イベント報酬券とお引き換えいたしますね", 0.0, 1);
